#!/usr/bin/env bash
# Autogenerated test: runs as the remote user inside a container built from each compatibility image with incus
# installed with default options, after the entrypoint and the start check ran once.
set -euo pipefail

# shellcheck source=/dev/null
source dev-container-features-test-lib
# shellcheck source=/dev/null
source "$(dirname "$0")/helpers.sh"

check "incus is on PATH and reports a version" incus --version
check "the entrypoint and the start check exist and are executable" test -x "${INCUS_START}" -a -x "${INCUS_CHECK}"
check "the container is privileged" container_is_privileged
check "the container's first process is the init the feature requests" container_has_init
check "the volume is mounted at /var/lib/incus" grep -q ' /var/lib/incus ' /proc/self/mounts
check "the repository definition names the stable channel, the image's suite, and the key file" \
  sources_name_channel stable
check "incus-client is installed from the Zabbly repository" zabbly_package_installed incus-client
check "incus-base is installed from the Zabbly repository" zabbly_package_installed incus-base
check "the package incus, with virtual machine support, is not installed by default" package_absent incus
check "the start check exits zero" "${INCUS_CHECK}"
check "the start record reports a started daemon" test "$(record_field result)" = started
check "the start record reports the first initialization as done" \
  test "$(record_field initialization)" = "done: incus admin init --minimal"
check "the start record is not writable by the remote user unless that user is root" \
  bash -c "test \"\$(id -u)\" = 0 || ! test -w ${INCUS_RECORD}"
check "the daemon runs" daemon_runs
check "the remote user lists instances without sudo" incus list
check "the remote user is root or a member of incus-admin" root_or_admin_member
check "the first initialization created a storage pool" has_storage_pool
check "the first initialization created a managed bridge" has_managed_network
check "an instance starts and gets an address on the managed bridge" instance_starts_with_address
check "the instance has no memory controller, and a memory limit is not applied" instance_limit_not_applied
check "the instance is removed" remove_instance
check "no ended incusd process remains uncollected" no_ended_daemon_process
check "the install left no GnuPG directory in the remote user's home or in root's" no_gnupg_home

reportResults
